#!/usr/bin/env bash
# Host tests for the fridge node's logic. Needs g++ and python, nothing else - no Arduino IDE,
# no ESP32 core, no board. It runs the core logic against vectors generated by the real Python signer
# and then compiles the sketch itself against shim/, in every transport and TLS configuration.
#
#   bash firmware/tests/run_tests.sh
#
# Point it at a running API to also prove that a body signed by the node's own signer is accepted:
#
#   API_BASE=http://127.0.0.1:8000 bash firmware/tests/run_tests.sh
set -euo pipefail
cd "$(dirname "$0")"

PY=${PYTHON:-python}
CXX=${CXX:-g++}

"$PY" gen_vectors.py vectors.txt
mkdir -p build
"$CXX" -std=c++11 -Wall -Wextra -I../coldchain_node -o build/test_core test_core.cpp
./build/test_core vectors.txt

# The sketch itself cannot run here, but every member name, argument count and #if branch in it can be
# checked against shim/ - the stand-in Arduino headers - with the example config, which is the file a
# newcomer actually copies. This is what catches a call to a function that does not exist: the board
# never gets flashed by the person who wrote it.
rc=0
for variant in "mqtt" "mqtt-tls" "http" "http-pinned"; do
  d=$(mktemp -d)
  cp ../coldchain_node/coldchain_node.ino ../coldchain_node/coldchain_core.h \
     ../coldchain_node/sha256_hmac.h "$d/"
  case "$variant" in
    http*)
      sed 's|^#define INGEST_TRANSPORT INGEST_MQTT$|#define INGEST_TRANSPORT INGEST_HTTP|' \
          ../coldchain_node/cc_config.example.h > "$d/cc_config.h" ;;
    *) cp ../coldchain_node/cc_config.example.h "$d/cc_config.h" ;;
  esac
  case "$variant" in
    mqtt-tls)
      sed -i -e 's|^#define MQTT_USE_TLS    0|#define MQTT_USE_TLS    1|' \
             -e 's|^#define MQTT_USER       ""|#define MQTT_USER       "bench-user"|' \
             -e 's|^#define MQTT_PASS       ""|#define MQTT_PASS       "bench-pass"|' "$d/cc_config.h"
      printf '#define MQTT_CA_CERT "PEM"\n' >> "$d/cc_config.h" ;;
    http-pinned) printf '#define API_CA_CERT "PEM"\n' >> "$d/cc_config.h" ;;
  esac
  if "$CXX" -fsyntax-only -std=c++11 -Wall -Wextra -Ishim -I"$d" -x c++ "$d/coldchain_node.ino"
  then echo "PASS  sketch compiles ($variant)"
  else echo "FAIL  sketch does not compile ($variant)"; rc=1
  fi
  rm -rf "$d"
done
[ "$rc" = 0 ] || exit 1

if [ -n "${API_BASE:-}" ]; then
  # no default: a signing key written into a test script is a leaked signing key
  KEY="${HMAC_SECRET_KEY:?run with HMAC_SECRET_KEY set to the fleet key of that API}"
  NONCE=$("$PY" -c "import uuid;print(uuid.uuid4().hex)")
  TS=$("$PY" -c "import time;print(int(time.time()))")
  BODY=$(./build/test_core --payload "$KEY" "${DEVICE_ID:-fridge-1}" "$NONCE" 5.4 "$TS" 97 0 1 0 0)
  REPLY=$(mktemp)
  CODE=$(curl -sS -o "$REPLY" -w '%{http_code}' -X POST "$API_BASE/api/sensor" \
         -H 'Content-Type: application/json' -d "$BODY")
  echo "live ingest -> HTTP $CODE $(cat "$REPLY")"
  rm -f "$REPLY"
  if [ "$CODE" != "201" ]; then
    echo "FAIL: the API rejected a body signed by the node's own signer"
    exit 1
  fi
fi
